async function getUserProfile(userId) {
  try {
    const user = await api.getUser(userId);
    const posts = await api.getPosts(userId);
    return { user, posts };
  } catch (error) {
    console.error(`Failed to fetch profile for user ${userId}:`, error.message);
    throw error;
  }
}

async function getUserProfiles(userIds) {
  try {
    const users = await Promise.all(userIds.map(id => api.getUser(id)));
    return users;
  } catch (error) {
    console.error("Failed to fetch users:", error.message);
    throw error;
  }
}

async function buildUserReport(userId) {
  try {
    const user = await api.getUser(userId);
    const posts = await api.getPosts(userId);
    const postsWithComments = await Promise.all(
      posts.map(async post => {
        const comments = await api.getComments(post.id);
        return { ...post, comments };
      })
    );
    return { user, posts: postsWithComments };
  } catch (error) {
    console.error("Failed to build report:", error.message);
    throw error;
  }
}

async function fetchWithBackoff(fn, maxRetries = 3) {
  for (let i = 0; i < maxRetries; i++) {
    try {
      return await fn();
    } catch (error) {
      if (i === maxRetries - 1) throw error;
      const delay = Math.pow(2, i) * 1000;
      console.log(`Retry ${i + 1} after ${delay}ms`);
      await new Promise(resolve => setTimeout(resolve, delay));
    }
  }
}
